		void RemoveToolStripButton_Click(object sender, EventArgs e)
		{
			var selectedItems = PackingGrid.SelectedElements;
			if (selectedItems.Length > 0)
			{
				var packages = selectedItems.Cast<WhsItemPackageState>();
				((TransitWarehousePackagePlanner)DataSource).RemovePackageStates(packages);
			}
			else
			{
				Globals.Message.ShowError(Res.GetString("cc3f259e-9c6b-4700-accb-8dc1b03a0af8", "Select One or More Packages to Remove."));
			}
		}

		void AssignToolStripButton_Click(object sender, EventArgs e)
		{
			var selectedItems = PackLineFilterStripControl.Grid.SelectedElements;
			if (selectedItems.Length > 0)
			{
				var planner = (TransitWarehousePackagePlanner)DataSource;
				var packages = selectedItems.Cast<WhsItemPackageState>();

				if (packages.Any(p => p.HandlingUnit != null && p.HandlingUnit.Package != null && p.HandlingUnit.Package.KP_KPH_PackageHeader == ZGuid.Empty))
				{
					Globals.Message.ShowError(Res.GetString("711b499b-048a-44ee-bb48-703fcef245cf", "Cannot assign any packages because a selected package belongs to a unlabeled handling unit."));
				}
				else if (packages.Any(p =>
							(!p.ParentJobNumber.IsEmpty && p.ParentJobNumber != planner.Parent.JobNumber)
							|| !p.WPS_WDC_TransitDispatchConsignment.IsEmpty
							|| (p.WPS_IsHandlingUnit && !p.DispatchConsignmentID.IsEmpty)))
				{
					Globals.Message.ShowError(Res.GetString("3604f251-5d4e-4145-8c79-d34aa7f7b841", "Cannot assign any package that has been attached to another Job or added to a Dispatch Consignment."));
				}
				else if (packages.Any(p => !p.WPS_IsHandlingUnit && p.WPS_WRC_TransitReceiveConsignment.IsEmpty))
				{
					Globals.Message.ShowError(Res.GetString("70731dbe-0351-46d0-b2d6-a3a869350a4c", "Packages aren't attached to a Receive Consignment so cannot be assigned to the shipment."));
				}
				else if (packages.Any(p => (p.WPS_IsHandlingUnit && p.GetHandlingUnitChildPackages().Any(inner => inner.WPS_WRC_TransitReceiveConsignment.IsEmpty)) || (p.HandlingUnit != null && p.HandlingUnit.GetHandlingUnitChildPackages().Any(inner => inner.WPS_WRC_TransitReceiveConsignment.IsEmpty))))
				{
					Globals.Message.ShowError(Res.GetString("8be1be49-1c13-46cd-a78d-450c2ca5b206", "Handling Unit's Child Packages aren't attached to a Receive Consignment so cannot be assigned to the shipment."));
				}
				else
				{
					var packagesWithHUs = packages.Where(p => p.HandlingUnit != null).ToList();
					bool assignAllPackage = false;
					if (packagesWithHUs.Any())
					{
						var distinctHUs = packagesWithHUs.Select(p => p.HandlingUnit).Distinct().ToList();

						foreach (var hu in distinctHUs)
						{
							var huChildPackages = hu.GetHandlingUnitChildPackages().ToList();
							var selectedChildPackages = packages.Where(p => p.HandlingUnit == hu).ToList();
							if (huChildPackages.Any() && selectedChildPackages.Count < huChildPackages.Count)
							{
								string message;
								if (distinctHUs.Count == 1)
								{
									message = Res.GetString("b7c4e912-3a5d-4f8b-9c2a-6e4f1d870b3e",
										$"Some of the selected packages are already packed onto HU {hu.Package.KP_PackageID}.\r\nDo you want to attach all other packages on this HU too?");
								}
								else
								{
									var huList = string.Join("\r\n", distinctHUs.Select(h => h.Package.KP_PackageID).OrderBy(x => x));
									message = Res.GetString("c9d2f567-4b8e-5c1a-8d3b-7f5a2e931c4f",
										"Some of the selected packages are already packed onto the following HUs:\r\n{0}\r\nDo you want to attach all remaining packages from these HUs as well?", huList);
								}

								var result = Globals.Message.Show(message, Res.GetString("e3a9b678-5c2f-4d9c-8e4a-9g6b3h024d5e", "Warning"),
									MessageBoxButtons.YesNo, MessageBoxIcon.Question);
								assignAllPackage = (result == DialogResult.Yes);
								break;
							}
						}
					}
					planner.AssignPackageState(packages, assignAllPackage);
				}
			}
			else
			{
				Globals.Message.ShowError(Res.GetString("0f236119-8bb5-454b-bfb3-049a6d37ce08", "Select One or More Packages to Attach."));
			}
		}

		void Cancel_Click(object sender, EventArgs e)
		{
			((TransitWarehousePackagePlanner)DataSource).Cancel();
			Close();
		}

		void CreatePackLines_Click(object sender, EventArgs e)
		{
			var planner = (TransitWarehousePackagePlanner)DataSource;
			var packagesToRemove = planner.ModuleFilterPackageCollection.Where(p => p.IsRemovedFromAttachedPacklinesAndHasJobNumber).ToArray();
			if (packagesToRemove.Any())
			{
				var numberOfOuterPackagesToRemove = packagesToRemove.Count(p => !p.WPS_IsHandlingUnit);
				var numberOfOverpacksToRemove = packagesToRemove.Count(p => p.WPS_UnitType == PackageStateUnitType.Codes.Overpack);
				if (numberOfOverpacksToRemove > 0)
				{
					Globals.Message.ShowWarning(numberOfOuterPackagesToRemove > 0 ?
						Res.GetString("a32baf45-82f6-46e2-80f9-807cb52b04f5", "You have removed {0} Package(s) and {1} Overpack(s). These Packlines will be removed from the Shipment.\r\nDetaching an overpack with inner packlines will remove the inner packlines from the Shipment.", numberOfOuterPackagesToRemove, numberOfOverpacksToRemove)
						: Res.GetString("e6395c39-8bf1-49e9-89b7-f6f7ad880c91", "You have removed {0} Overpack(s). These Packlines will be removed from the Shipment.\r\nDetaching an overpack with inner packlines will remove the inner packlines from the Shipment.", numberOfOverpacksToRemove));
				}
				else
				{
					Globals.Message.ShowWarning(Res.GetString("c31195ff-d01a-4a5e-b41f-e60f2e149df2", "You have removed {0} Package(s). These Packlines will be removed from the Shipment.", numberOfOuterPackagesToRemove));
				}
			}

			var availableStatus = new List<string> {
				AttachablePackageStateStatuses.Codes.ARV,
				AttachablePackageStateStatuses.Codes.CTT,
				AttachablePackageStateStatuses.Codes.PIC,
				AttachablePackageStateStatuses.Codes.PUT,
				AttachablePackageStateStatuses.Codes.STA
			};
			var attachedIncompleteRCN = planner.AttachedPackages
				.Select(p => p.ReceiveConsignment)
				.Distinct()
				.SelectMany(r => r.PackageStates)
				.Where(p =>
					availableStatus.Contains(p.WPS_Status) &&
					!p.AdditionalReferenceNumbers.Cast<ICusEntryNumber>().Any(t =>
						t.CE_EntryType == WarehouseAdditionalReferenceTypes.Codes.BookingPartyReference &&
						(t.CE_EntryNum == planner.Parent.JobNumber || t.CE_EntryNum.IsEmpty)
					) &&
					(string.IsNullOrEmpty(p.ParentJobNumber) || p.ParentJobNumber == planner.Parent.JobNumber) &&
					p.WPS_WDC_TransitDispatchConsignment.IsEmpty &&
					(p.HandlingUnitCache == null || (!p.HandlingUnitCache.Package.KP_KPH_PackageHeader.IsEmpty && p.HandlingUnitCache.WPS_UnitType != PackageStateUnitType.Codes.Overpack)) &&
					(!p.WPS_IsHandlingUnit || p.DispatchConsignmentID.IsEmpty) &&
					!p.IsAddedToAttachedPackageCollection ||
					p.IsRemovedFromAttachedPacklinesAndHasJobNumber
				)
				.Select(p => p.ReceiveConsignment)
				.Distinct()
				.OrderByDescending(rcn => rcn.WRC_JobID)
				.Select(p => string.Format(CultureInfo.InvariantCulture, "{0} - {1}", p.WRC_JobID, p.WRC_ConsignmentID)); // SuppressCodeSmell Reason = List the RCNs as "<JobID> - <Consignment ID>"

			var result = DialogResult.Yes;
			var warningResString = Res.GetString("05db3bf7-5375-445e-b3b3-e6d130697c72", "Warning");
			if (attachedIncompleteRCN.Any())
			{
				var message = Res.GetString("7a48ebe8-74d3-4a8a-979f-41a72d8c416c", "You did not add all packages from the following RCNs:\r\n{0}\r\n\r\nContinue anyway?", string.Join("\r\n", attachedIncompleteRCN));
				result = Globals.Message.Show(message, warningResString, MessageBoxButtons.YesNo, MessageBoxIcon.Question);
			}

			if (result == DialogResult.Yes)
			{
				var AttachingPackages = planner.AttachedPackages.Where(a => string.IsNullOrEmpty(a.ParentJobNumber)).ToArray();
				var preAttachingValidationMessage = planner.Parent.GetPreAttachingValidationMessage(AttachingPackages);

				var attachingRCNs = AttachingPackages.Select(p => p.ReceiveConsignment).Distinct();
				var shipmentCodes = attachingRCNs.Where(r => !string.IsNullOrEmpty(r.ShipmentNumber)).Select(r => r.ShipmentNumber).Distinct();
				if (shipmentCodes.Count() > 5)
				{
					Globals.Message.Show(Res.GetString("ff936dca-d516-4e4e-adb0-cfdb012a865b", "Attaching packages from more than five (5) Receive Consignments (RCNs) is not supported. Please adjust the package selection to reduce the number of RCNs and try again."), warningResString, MessageBoxButtons.OK, MessageBoxIcon.Error);
				}
				else if (preAttachingValidationMessage.IsEmpty
					|| Globals.Message.Show(preAttachingValidationMessage, warningResString, MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
				{
					planner.RemovePacklineFromPreviousParent();
					planner.CreatePackLines();
					planner.SetParentTranportCompany();
					Close();
				}
			}
		}

